int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<int>> adj(n + 1);
    for (const vector<long long>& e : edges) {
        adj[e[0]].push_back((int)e[1]);
        adj[e[1]].push_back((int)e[0]);
    }
    for (int v = 1; v <= n; v++) {
        sort(adj[v].begin(), adj[v].end());
        cout << adj[v].size();
        for (int w : adj[v]) cout << " " << w;
        cout << "\n";
    }

    return 0;
}

